#!/usr/bin/env ruby

FILE = 'chapters/med_terms_h.tex'

DEFINITIONS = {
  'habit' => 'A repeated behavior or pattern of action that may be ordinary, helpful, or harmful; in clinical assessment, its frequency, control, and effect on functioning determine whether it is a concern.',
