text = File.read(FILE)
changed = 0
text = text.gsub(/^\\medterm\{([^}]*)\} ([^\n]*)/) do |line|
  term = Regexp.last_match(1)
  definition = DEFINITIONS[term]
  if definition
    changed += 1
    "\\medterm{#{term}} #{definition}"
  else
    line
  end
end
File.write(FILE, text)
puts "updated=#{changed}"
